def gen_coins(rng):
    coins = sorted([1] + rng.sample(range(2, 10), 2))
    return coins, rng.randint(1, 20)


def gen_canonical(rng):
    return [1, 2, 5, 10], rng.randint(1, 40)


def greedy_coins(case):
    coins, amount = case
    used = 0
    for c in sorted(coins, reverse=True):
        used += amount // c
        amount %= c
    return used


def min_coins_brute(case):
    coins, amount = case
    best = [0] + [float("inf")] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and best[a - c] + 1 < best[a]:
                best[a] = best[a - c] + 1
    return best[amount]


def trials_run(gen, trials, seed):
    # the learner's answer, and how many times gen was called
    calls = [0]

    def counting_gen(rng):
        calls[0] += 1
        return gen(rng)

    found = greedy_counterexample(greedy_coins, min_coins_brute, counting_gen, trials, seed)
    return found, calls[0]

