import random


def greedy_counterexample(greedy, brute, gen, trials, seed):
    rng = random.Random(seed)
    best = None
    for _ in range(trials):
        case = gen(rng)
        if greedy(case) != brute(case):
            if best is None or case[1] < best[1]:
                best = case
    return best
